    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    moveFace(context, id + "move1", { "moveFaces" : qUnion([qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(30, 10, 5) * millimeter), qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(15, 20, 5) * millimeter)]), "moveFaceType" : MoveFaceType.OFFSET, "offsetDistance" : 1.5 * millimeter });
}

// move-face: translate a side 6 mm along x
export function c044(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const dirX = newSketchOnPlane(context, id + "dirX", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(dirX, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirX);
    moveFace(context, id + "move1", { "moveFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(30, 10, 5) * millimeter), "moveFaceType" : MoveFaceType.TRANSLATE, "direction" : qCreatedBy(id + "dirX", EntityType.EDGE), "translationDistance" : 6 * millimeter });
}

// move-face: translate a hole 4 mm along y
export function c045(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter });
    const toolSketch = newSketchOnPlane(context, id + "toolSketch", { "sketchPlane" : plane(vector(0, 0, -5) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(toolSketch, "circle1", { "center" : vector(15, 10) * millimeter, "radius" : 5 * millimeter });
    skSolve(toolSketch);
    extrude(context, id + "tool", { "entities" : qSketchRegion(id + "toolSketch"), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter });
    booleanBodies(context, id + "cut1", { "operationType" : BooleanOperationType.SUBTRACTION, "targets" : qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), "tools" : qBodyType(qCreatedBy(id + "tool", EntityType.BODY), BodyType.SOLID) });
    const dirY = newSketchOnPlane(context, id + "dirY", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(1, 0, 0), vector(0, 1, 0)) });
    skLineSegment(dirY, "line1", { "start" : vector(0, 0) * millimeter, "end" : vector(1, 0) * millimeter });
    skSolve(dirY);
    moveFace(context, id + "move1", { "moveFaces" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.FACE), vector(20, 10, 5) * millimeter), "moveFaceType" : MoveFaceType.TRANSLATE, "direction" : qCreatedBy(id + "dirY", EntityType.EDGE), "translationDistance" : 4 * millimeter });
}

